,"sizeBytes":{"type":"integer"},"md5":{"type":"string","description":"Hex md5 of the exact bytes attached"}},"required":["documentId","filename","contentType","sizeBytes","md5"]},"description":"The files this reply carried. Absent when it carried none."}},"required":["transport","instantlyCampaignId","leadEmail","accountEmail","from","subject","cc","messageId","inReplyTo"]}},"required":["success","status","reply"]}}],"needsTheirYes":{"why":"Sends a reply to a person in their email thread.","because":["sends_to_person"],"notNeededWhen":[]}}
